figure.sourcecode:
Etime = #6.1001(etime-detailed)
etime-framework = { uint => any ; 少なくとも1つの基準時刻 * (nint/text) => any ; 選択的な補足情報 * uint => any ; クリティカルな補足情報 }
etime-detailed = ({ $$ETIME-BASETIME ClockQuality-group * $$ETIME-ELECTIVE * $$ETIME-CRITICAL * ((nint/text) .feature "etime-elective-extension") => any * (uint .feature "etime-critical-extension") => any }) .within etime-framework
